package com.wizzadrds.theworldremembers.knowledge; import com.mojang.serialization.Codec; import net.minecraft.resources.Identifier; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import java.util.*; public final class KnowledgeManager extends SavedData{private static final Codec<KnowledgeManager> CODEC=KnowledgeFact.CODEC.listOf().xmap(list->{var x=new KnowledgeManager();x.facts.addAll(list);return x;},x->x.facts); private static final SavedDataType<KnowledgeManager> TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","knowledge"),KnowledgeManager::new,CODEC,null); private final List<KnowledgeFact> facts=new ArrayList<>(); public static KnowledgeManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new KnowledgeManager():l.getDataStorage().computeIfAbsent(TYPE);} public void witness(UUID knower,UUID subject,String eventType,long tick){put(new KnowledgeFact(knower,subject,eventType,knower,KnowledgeOrigin.DIRECT,100,tick,tick));} public boolean report(UUID speaker,UUID listener,UUID subject,String eventType,long tick){KnowledgeFact source=findBest(speaker,subject,eventType);if(source==null)return false;KnowledgeOrigin origin=source.origin()==KnowledgeOrigin.DIRECT?KnowledgeOrigin.REPORTED:KnowledgeOrigin.RUMORED;int confidence=Math.max(0,source.confidence()- (origin==KnowledgeOrigin.RUMORED?25:10));put(new KnowledgeFact(listener,subject,eventType,speaker,origin,confidence,source.observedTick(),tick));return true;} public Optional<KnowledgeFact> findBest(UUID knower,UUID subject,String eventType){return facts.stream().filter(f->f.knower().equals(knower)&&f.subject().equals(subject)&&f.eventType().equals(eventType)).max(Comparator.comparingInt(f->f.origin()==KnowledgeOrigin.DIRECT?3:f.origin()==KnowledgeOrigin.REPORTED?2:1).thenComparingInt(KnowledgeFact::confidence));} public List<KnowledgeFact> factsOf(UUID knower){return facts.stream().filter(f->f.knower().equals(knower)).toList();} private void put(KnowledgeFact fact){facts.removeIf(f->f.knower().equals(fact.knower())&&f.subject().equals(fact.subject())&&f.eventType().equals(fact.eventType())&&f.origin()!=KnowledgeOrigin.DIRECT);facts.add(fact);setDirty();}}
